# ============================================================
#  Utilidades
# ============================================================
def cop(x, dec=0):
    """Formato numérico estilo Colombia: 1.234.567,8"""
    s = f"{x:,.{dec}f}"
    return s.replace(",", "§").replace(".", ",").replace("§", ".")


def kpi(col, titulo, valor, sub=""):
    col.markdown(
        f'<div class="kpi"><div class="kpi-t">{titulo}</div>'
        f'<div class="kpi-v">{valor}</div><div class="kpi-s">{sub}</div></div>',
        unsafe_allow_html=True,
    )


def nota(texto):
    st.markdown(f'<div class="nota">📌 <b>Lectura:</b> {texto}</div>', unsafe_allow_html=True)


def estilo(fig, alto=330):
    fig.update_layout(
        height=alto, margin=dict(l=10, r=10, t=55, b=10),
        paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(0,0,0,0)",
        font=dict(color=INK, family="Georgia, serif", size=12),
        title_font=dict(size=15, color=INK),
        legend=dict(bgcolor="rgba(0,0,0,0)"),
    )
    fig.update_xaxes(gridcolor=LINE, zerolinecolor=LINE)
    fig.update_yaxes(gridcolor=LINE, zerolinecolor=LINE)
    return fig


@st.cache_data
def cargar_datos():
    crudo = gzip.decompress(base64.b64decode(DATOS_B64))
    df = pd.read_csv(io.BytesIO(crudo))
    df["Transaction Date"] = pd.to_datetime(df["Transaction Date"], errors="coerce")
    return df


df = cargar_datos()

