# ============================================================
#  VISTA 1 · General
# ============================================================
def vista_general(d):
    st.subheader("Vista General")
    st.caption("¿Cómo va el negocio en su conjunto?")

    c1, c2, c3, c4 = st.columns(4)
    kpi(c1, "Ventas totales", f"${cop(d['Total Spent'].sum())}")
    kpi(c2, "Transacciones", f"{cop(len(d))}")
    kpi(c3, "Ticket promedio", f"${cop(d['Total Spent'].mean(), 1)}")
    kpi(c4, "Clientes", f"{d['Customer ID'].nunique()}")
    st.write("")

    # Evolución mensual
    s = d.dropna(subset=["Transaction Date"]).copy()
    s["mes"] = s["Transaction Date"].dt.to_period("M").dt.to_timestamp()
    serie = s.groupby("mes")["Total Spent"].sum().reset_index()
    fig = px.line(serie, x="mes", y="Total Spent", markers=True,
                  title="Evolución mensual de ventas", color_discrete_sequence=[ACCENT])
    fig.update_traces(line=dict(width=2))
    st.plotly_chart(estilo(fig), use_container_width=True)
    nota("Las ventas se mantienen estables mes a mes (negocio estacionario): no hay una "
         "tendencia clara de crecimiento ni caída en el periodo.")

    col1, col2 = st.columns(2)
    with col1:
        canal = d["Location"].value_counts().reset_index()
        canal.columns = ["Canal", "Transacciones"]
        fig = px.pie(canal, names="Canal", values="Transacciones", hole=0.55,
                     title="Mezcla por canal", color_discrete_sequence=SECUENCIA)
        st.plotly_chart(estilo(fig), use_container_width=True)
    with col2:
        pago = d["Payment Method"].value_counts().reset_index()
        pago.columns = ["Método", "Transacciones"]
        fig = px.pie(pago, names="Método", values="Transacciones", hole=0.55,
                     title="Mezcla por método de pago", color_discrete_sequence=SECUENCIA)
        st.plotly_chart(estilo(fig), use_container_width=True)

    ventas_cat = d.groupby("Category")["Total Spent"].sum().sort_values().reset_index()
    fig = px.bar(ventas_cat, x="Total Spent", y="Category", orientation="h",
                 title="Ventas por categoría", color_discrete_sequence=[BLUE])
    st.plotly_chart(estilo(fig, 360), use_container_width=True)


# ============================================================
#  VISTA 2 · Efectividad de Descuentos (el gancho + correcciones)
# ============================================================
def vista_descuentos(d):
    st.subheader("Efectividad de Descuentos")
    st.caption("¿El programa de descuentos genera ventas adicionales o es dinero perdido?")

    # --- Banner con el hallazgo central ---
    con = d.loc[d["Discount Applied"] == "Sí", "Total Spent"].mean()
    sin = d.loc[d["Discount Applied"] == "No", "Total Spent"].mean()
    efecto = (con - sin) if (pd.notna(con) and pd.notna(sin)) else 0.0
    st.markdown(
        '<div class="banner">'
        '<div class="banner-k">≈ $0</div>'
        '<div class="banner-t">El descuento NO aumenta el ticket promedio</div>'
        '<div class="banner-s">El análisis contrafactual del Avance 2 estimó un efecto marginal de '
        '<b>−$0,27 por transacción</b>, equivalente a un costo aproximado de '
        '<b>$54.822 anuales</b> entregados sin retorno medible.</div>'
        '</div>',
        unsafe_allow_html=True,
    )
    st.write("")

    # --- CORRECCIÓN 1: explicar el tema de los descuentos ---
    with st.expander("❓ ¿Qué es esto y cómo se mide? (leer primero)", expanded=True):
        st.markdown("""
**El programa de descuentos.** El comercio aplica descuentos en aproximadamente la mitad
de sus transacciones registradas. La pregunta de negocio es simple: *¿ese descuento hace
que la gente compre más, o solo regala margen?*

**Cómo se mide (análisis contrafactual).** No existe un monto de descuento en los datos,
solo una marca de si la transacción tuvo descuento (**Sí**), no lo tuvo (**No**) o no quedó
registrado (**Sin registro**). Por eso comparamos el **ticket promedio** (lo que gasta el
cliente) entre las transacciones **con** y **sin** descuento. Si el descuento funcionara,
las transacciones con descuento deberían mostrar un ticket más alto.

**Efecto marginal.** Es la diferencia de ticket entre ambos grupos. Un efecto cercano a
**cero** significa que el descuento no cambia lo que el cliente gasta: es dinero entregado
sin generar venta adicional.
""")

    # --- KPIs del descuento ---
    con_n = int((d["Discount Applied"] == "Sí").sum())
    no_n = int((d["Discount Applied"] == "No").sum())
    sr_n = int((d["Discount Applied"] == "Sin registro").sum())
    total = len(d)
    c1, c2, c3 = st.columns(3)
    kpi(c1, "Efecto marginal (este corte)", f"${cop(efecto, 2)}", "ticket Sí − ticket No")
    kpi(c2, "Transacciones con descuento", f"{con_n / total * 100:.1f}%", f"{cop(con_n)} de {cop(total)}")
    kpi(c3, "Costo anual estimado", "$54.822", "según contrafactual Avance 2")
    st.write("")

    col1, col2 = st.columns(2)
    with col1:
        # Ticket promedio por estado (3 barras casi idénticas)
        tk = d.groupby("Discount Applied")["Total Spent"].mean().reindex(
            ["No", "Sí", "Sin registro"]).reset_index()
        tk.columns = ["Estado", "Ticket"]
        fig = px.bar(tk, x="Estado", y="Ticket", text="Ticket",
                     title="Ticket promedio por estado de descuento",
                     color="Estado", color_discrete_sequence=SECUENCIA)
        fig.update_traces(texttemplate="$%{text:,.1f}", textposition="outside")
        st.plotly_chart(estilo(fig), use_container_width=True)
        nota("Las tres barras son casi idénticas: con o sin descuento, el cliente gasta lo mismo.")
    with col2:
        # Histograma del efecto marginal por ítem (distribución centrada en cero)
        sub = d[d["Discount Applied"].isin(["Sí", "No"])]
        piv = sub.pivot_table(index="Item", columns="Discount Applied",
                              values="Total Spent", aggfunc="mean").dropna()
        piv["efecto"] = piv["Sí"] - piv["No"]
        fig = px.histogram(piv, x="efecto", nbins=30,
                           title="Distribución del efecto del descuento por ítem",
                           color_discrete_sequence=[BLUE])
        fig.add_vline(x=0, line_dash="dash", line_color=RED)
        st.plotly_chart(estilo(fig), use_container_width=True)
        nota("La distribución se concentra alrededor de cero: no hay un efecto positivo "
             "sistemático del descuento sobre las ventas.")

    st.divider()

    # --- CORRECCIÓN 2: ¿qué causa que no sirvan? ---
    st.markdown("### ¿Por qué no funcionan? Análisis de causas")

    # (a) Cuánto descuento se hace
    col1, col2 = st.columns([1, 1])
    with col1:
        estados = pd.DataFrame({
            "Estado": ["Con descuento (Sí)", "Sin descuento (No)", "Sin registro"],
            "Transacciones": [con_n, no_n, sr_n],
        })
        fig = px.pie(estados, names="Estado", values="Transacciones", hole=0.55,
                     title="¿Cuánto se descuenta? Reparto de transacciones",
                     color_discrete_sequence=[ACCENT, GREEN, MUTED])
        st.plotly_chart(estilo(fig), use_container_width=True)
        nota(f"El descuento se aplica a cerca de la mitad de las transacciones registradas "
             f"(de forma masiva, no selectiva), y un {sr_n / total * 100:.0f}% ni siquiera "
             f"quedó registrado, lo que impide medir bien el programa.")
    with col2:
        # Penetración por categoría (¿se enfoca en alguna?)
        sub = d[d["Discount Applied"].isin(["Sí", "No"])].copy()
        pen = sub.groupby("Category")["Discount Applied"].apply(
            lambda g: (g == "Sí").mean() * 100).sort_values().reset_index()
        pen.columns = ["Category", "pen"]
        fig = px.bar(pen, x="pen", y="Category", orientation="h", text="pen",
                     title="Penetración del descuento por categoría (%)",
                     color_discrete_sequence=[ACCENT])
        fig.update_traces(texttemplate="%{text:.0f}%", textposition="outside")
        fig.update_xaxes(range=[0, 100])
        st.plotly_chart(estilo(fig), use_container_width=True)
        nota("Todas las categorías reciben descuento en una proporción parecida (~50%): "
             "se descuenta a todo por igual, sin una estrategia por categoría.")

    # (b) Efecto por categoría
    piv_c = sub.pivot_table(index="Category", columns="Discount Applied",
                            values="Total Spent", aggfunc="mean")
    piv_c["efecto"] = piv_c["Sí"] - piv_c["No"]
    piv_c = piv_c.sort_values("efecto").reset_index()
    colores = [GREEN if v > 0 else RED for v in piv_c["efecto"]]
    fig = go.Figure(go.Bar(
        x=piv_c["efecto"], y=piv_c["Category"], orientation="h",
        marker_color=colores, text=[f"${v:,.1f}" for v in piv_c["efecto"]],
        textposition="outside",
    ))
    fig.update_layout(title="Efecto del descuento sobre el ticket, por categoría (Sí − No)")
    fig.add_vline(x=0, line_color=INK)
    st.plotly_chart(estilo(fig, 360), use_container_width=True)
    nota("Donde el efecto es positivo (verde) el descuento parece ayudar; donde es negativo "
         "(rojo) el cliente con descuento gasta incluso menos. Las diferencias son pequeñas e "
         "inconsistentes, no justifican descontar en todas las categorías.")

    # (c) Decisiones
    mejores = piv_c[piv_c["efecto"] > 0]["Category"].tolist()
    mejores_txt = ", ".join(mejores[-3:]) if mejores else "ninguna de forma consistente"
    st.markdown("### 🧭 Decisiones sugeridas")
    st.markdown(
        f'<div class="deci">'
        f'<b>1. Suspender el descuento general.</b> Aplicarlo a ~50% de las ventas sin retorno '
        f'medible cuesta cerca de $54.822 al año. Empezar por apagarlo donde el efecto es negativo.<br><br>'
        f'<b>2. Pilotar descuentos selectivos.</b> Probar descuentos solo en las categorías con '
        f'efecto positivo observado ({mejores_txt}) y medir resultados antes de escalar.<br><br>'
        f'<b>3. Arreglar el registro del descuento.</b> Un tercio de las transacciones no tiene '
        f'registro; sin ese dato no se puede medir bien. Meta: capturar el descuento en &gt;95% de las ventas.<br><br>'
        f'<b>4. Redirigir el presupuesto.</b> Reinvertir lo que hoy se entrega a ciegas en los '
        f'clientes más valiosos (ver la vista de Clientes).'
        f'</div>',
        unsafe_allow_html=True,
    )


# ============================================================
#  VISTA 3 · Categorías
# ============================================================
def vista_categorias(d):
    st.subheader("Categorías")
    st.caption("¿Qué categorías impulsan los ingresos y cuáles requieren estrategias distintas?")

    g = d.groupby("Category").agg(
        ventas=("Total Spent", "sum"),
        transacciones=("Transaction ID", "count"),
        ticket=("Total Spent", "mean"),
    ).reset_index()

    top = g.sort_values("ventas").iloc[-1]
    c1, c2, c3 = st.columns(3)
    kpi(c1, "Categorías", f"{len(g)}")
    kpi(c2, "Categoría líder", f"{top['Category']}", f"${cop(top['ventas'])} en ventas")
    kpi(c3, "Ticket promedio global", f"${cop(d['Total Spent'].mean(), 1)}")
    st.write("")

    col1, col2 = st.columns(2)
    with col1:
        gv = g.sort_values("ventas")
        fig = px.bar(gv, x="ventas", y="Category", orientation="h",
                     title="Ventas por categoría", color_discrete_sequence=[BLUE])
        st.plotly_chart(estilo(fig, 380), use_container_width=True)
    with col2:
        gt = g.sort_values("ticket")
        fig = px.bar(gt, x="ticket", y="Category", orientation="h",
                     title="Ticket promedio por categoría", color_discrete_sequence=[ACCENT])
        st.plotly_chart(estilo(fig, 380), use_container_width=True)
    nota("Las ventas están relativamente repartidas entre categorías; ninguna domina de forma "
         "extrema. El ticket promedio es parecido entre ellas, coherente con un catálogo homogéneo.")


# ============================================================
#  VISTA 4 · Clientes
# ============================================================
def vista_clientes(d):
    st.subheader("Clientes")
    st.caption("¿Quiénes son mis clientes más valiosos y qué tan distintos son entre sí?")

    g = d.groupby("Customer ID").agg(
        ventas=("Total Spent", "sum"),
        transacciones=("Transaction ID", "count"),
        ticket=("Total Spent", "mean"),
    ).sort_values("ventas", ascending=False).reset_index()

    ventas_tot = g["ventas"].sum()
    top5 = g.head(5)["ventas"].sum()
    c1, c2, c3 = st.columns(3)
    kpi(c1, "Clientes", f"{len(g)}")
    kpi(c2, "Top 5 concentra", f"{top5 / ventas_tot * 100:.0f}%", "de las ventas")
    kpi(c3, "Ticket promedio", f"${cop(d['Total Spent'].mean(), 1)}")
    st.write("")

    top = g.head(10).sort_values("ventas")
    fig = px.bar(top, x="ventas", y="Customer ID", orientation="h",
                 title="Top 10 clientes por ventas", color_discrete_sequence=[BLUE])
    st.plotly_chart(estilo(fig, 380), use_container_width=True)

    col1, col2 = st.columns(2)
    with col1:
        fig = px.bar(g.sort_values("transacciones").tail(10),
                     x="transacciones", y="Customer ID", orientation="h",
                     title="Top 10 por número de compras", color_discrete_sequence=[GREEN])
        st.plotly_chart(estilo(fig, 360), use_container_width=True)
    with col2:
        fig = px.scatter(g, x="transacciones", y="ventas", size="ticket",
                         title="Frecuencia vs. valor por cliente",
                         color_discrete_sequence=[ACCENT], hover_name="Customer ID")
        st.plotly_chart(estilo(fig, 360), use_container_width=True)
    nota(f"La base es pequeña y recurrente ({len(g)} clientes). El top 5 concentra "
         f"{top5 / ventas_tot * 100:.0f}% de las ventas: conviene proteger esa relación con "
         f"beneficios dirigidos en vez de descuentos masivos.")


# ============================================================
#  VISTA 5 · Calidad de Datos
# ============================================================
def vista_calidad(d_full):
    st.subheader("Calidad de Datos")
    st.caption("¿Qué tan confiable es la información sobre la que estoy decidiendo?")

    total = len(d_full)
    sr = int((d_full["Discount Applied"] == "Sin registro").sum())

    c1, c2, c3 = st.columns(3)
    kpi(c1, "Descuento sin registro", f"{sr / total * 100:.0f}%", f"{cop(sr)} transacciones")
    kpi(c2, "Recuperado con imputación", "95,2%", "vs. 60,3% con borrado ingenuo")
    kpi(c3, "Transacciones útiles", f"{cop(total)}", "tras limpieza del Avance 1")
    st.write("")

    # Completitud por campo (indicadores tipo anillo)
    st.markdown("**Completitud por campo**")
    campos = {
        "Categoría": 100.0, "Ítem": 100.0, "Precio": 100.0,
        "Cantidad": 100.0, "Total gastado": 100.0,
        "Descuento": (1 - sr / total) * 100,
    }
    cols = st.columns(len(campos))
    for col, (campo, pct) in zip(cols, campos.items()):
        color = GREEN if pct >= 95 else (ACCENT if pct >= 70 else RED)
        fig = go.Figure(go.Indicator(
            mode="gauge+number", value=pct,
            number={"suffix": "%", "font": {"size": 22}},
            gauge={"axis": {"range": [0, 100], "visible": False},
                   "bar": {"color": color},
                   "bgcolor": "#EEE8DD"},
            title={"text": campo, "font": {"size": 13}},
        ))
        fig.update_layout(height=170, margin=dict(l=10, r=10, t=40, b=10),
                          paper_bgcolor="rgba(0,0,0,0)", font=dict(color=INK))
        col.plotly_chart(fig, use_container_width=True)
    nota("Tras la limpieza, casi todos los campos están completos. El punto débil es el "
         "registro del descuento: un tercio quedó sin capturar, justo el dato más importante "
         "para evaluar el programa.")

    col1, col2 = st.columns(2)
    with col1:
        comp = pd.DataFrame({
            "Estrategia": ["Imputación lógica", "Borrado ingenuo"],
            "Transacciones recuperadas (%)": [95.2, 60.3],
        })
        fig = px.bar(comp, x="Estrategia", y="Transacciones recuperadas (%)", text="Transacciones recuperadas (%)",
                     title="Recuperación de datos por estrategia",
                     color="Estrategia", color_discrete_sequence=[GREEN, RED])
        fig.update_traces(texttemplate="%{text}%", textposition="outside")
        fig.update_yaxes(range=[0, 105])
        st.plotly_chart(estilo(fig), use_container_width=True)
    with col2:
        st.markdown("**Meta de calidad**")
        st.markdown(
            f'<div class="deci">El campo crítico es el <b>registro del descuento</b>, hoy en '
            f'<b>{(1 - sr / total) * 100:.0f}%</b> de completitud.<br><br>'
            f'<b>Meta:</b> llevar la captura del descuento a <b>&gt;95%</b> ajustando el punto '
            f'de venta para que sea un campo obligatorio. Solo así el análisis de efectividad '
            f'será plenamente confiable.</div>',
            unsafe_allow_html=True,
        )


# ============================================================
#  Router de vistas
# ============================================================
if vista == "Vista General":
    vista_general(dff)
elif vista == "Efectividad de Descuentos":
    vista_descuentos(dff)
elif vista == "Categorías":
    vista_categorias(dff)
elif vista == "Clientes":
    vista_clientes(dff)
else:
    vista_calidad(df)  # calidad siempre sobre el dataset completo

st.write("")
st.caption("RetailLens · Avance 3 · Aplicación de visualización de datos · datos incrustados en la app.")
